import test from 'node:test';import assert from 'node:assert/strict';import {GameRoom} from '../worker/index.js';test('a later joiner becomes host if the original host disconnected before anyone else joined',async()=>{const storage=new Map();const state={storage:{get:async k=>storage.get(k),put:async(k,v)=>storage.set(k,structuredClone(v))},blockConcurrencyWhile:fn=>fn()};const room=new GameRoom(state,{});await room.ready;const first={send(){},close(){}};room.sessions.set('s0',first);await room.join('s0',first,{type:'CREATE',code:'ABC123',name:'P0'});await room.disconnect('s0');const second={send(){},close(){}};room.sessions.set('s1',second);await room.join('s1',second,{type:'JOIN',code:'ABC123',name:'P1'});assert.equal(room.view(room.room.players[1].id).isHost,true);});
